sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
uniform float blur;
uniform float alpha;
uniform float fill;
uniform float fade;
uniform float spread;
uniform float offset;
float erfinv(float x) {
    float w = -log(max((1.0 - x) * (1.0 + x), 0.0000001));
    float p;
    if (w < 5.0) {
        w -= 2.5;
        p = 2.81022636e-08;
        p = 3.43273939e-07 + p * w;
        p = -3.5233877e-06 + p * w;
        p = -4.39150654e-06 + p * w;
        p = 0.00021858087 + p * w;
        p = -0.00125372503 + p * w;
        p = -0.00417768164 + p * w;
        p = 0.246640727 + p * w;
        p = 1.50140941 + p * w;
    } else {
        w = sqrt(w) - 3.0;
        p = -0.000200214257;
        p = 0.000100950558 + p * w;
        p = 0.00134934322 + p * w;
        p = -0.00367342844 + p * w;
        p = 0.00573950773 + p * w;
        p = -0.0076224613 + p * w;
        p = 0.00943887047 + p * w;
        p = 1.00167406 + p * w;
        p = 2.83297682 + p * w;
    }
    return p * x;
}
float outside(float b) { return max(blur, 0.0) / 3.0 * 1.41421356 * erfinv(1.0 - 2.0 * clamp(b, 0.002, 0.998)); }
float hit(float2 p, float a, float r) {
    float2 u = float2(cos(a), sin(a));
    float lo = 0.0;
    float hi = -1.0;
    for (int i = 1; i <= 12; i++) {
        float s = r * float(i) / 12.0;
        if (float(image.eval(p + u * s).a) >= 0.5) {
            hi = s;
            break;
        }
        lo = s;
    }
    if (hi < 0.0) return r;
    for (int i = 0; i < 5; i++) {
        float m = 0.5 * (lo + hi);
        if (float(image.eval(p + u * m).a) >= 0.5) hi = m; else lo = m;
    }
    return 0.5 * (lo + hi);
}
float apart(float2 coord, float b, float r) {
    float est = outside(b);
    if (b > 0.6 || est > r * 1.5 + 4.0) return est;
    float gx = float(blurred.eval(coord + float2(1.0, 0.0)).a - blurred.eval(coord - float2(1.0, 0.0)).a);
    float gy = float(blurred.eval(coord + float2(0.0, 1.0)).a - blurred.eval(coord - float2(0.0, 1.0)).a);
    if (abs(gx) + abs(gy) < 0.000001) return est;
    float base = atan(gy, gx);
    float best = r;
    float at = base;
    for (int k = -2; k <= 2; k++) {
        float a = base + float(k) * 0.5235988;
        float h = hit(coord, a, r);
        if (h < best) {
            best = h;
            at = a;
        }
    }
    if (best >= r) return r;
    float lo = at - 0.5235988;
    float hi = at + 0.5235988;
    float x1 = hi - 0.618034 * (hi - lo);
    float x2 = lo + 0.618034 * (hi - lo);
    float f1 = hit(coord, x1, r);
    float f2 = hit(coord, x2, r);
    for (int i = 0; i < 8; i++) {
        if (f1 < f2) {
            hi = x2;
            x2 = x1;
            f2 = f1;
            x1 = hi - 0.618034 * (hi - lo);
            f1 = hit(coord, x1, r);
        } else {
            lo = x1;
            x1 = x2;
            f1 = f2;
            x2 = lo + 0.618034 * (hi - lo);
            f2 = hit(coord, x2, r);
        }
    }
    return min(best, min(f1, f2));
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float b = float(blurred.eval(coord).a);
    float t;
    float cover;
    if (spread > 0.5) {
        float reach = max(blur * 0.6, offset + 0.001);
        float d = apart(coord, b, reach + 2.0);
        t = clamp((d - offset) / (reach - offset), 0.0, 1.0);
        cover = clamp(d - offset + 0.5, 0.0, 1.0) * clamp(reach - d + 0.5, 0.0, 1.0) * clamp(alpha, 0.0, 1.0) * (1.0 - float(src.a)) * clamp(blur, 0.0, 1.0);
        if (fade > 0.5) cover *= 1.0 - smoothstep(0.0, 1.0, t);
    } else {
        t = clamp(1.0 - b * 2.0, 0.0, 1.0);
        t *= t;
        cover = smoothstep(0.0, 0.06, b) * clamp(alpha, 0.0, 1.0);
        if (fade > 0.5) cover *= 1.0 - t;
    }
    float3 rgb = mix(float3(color1.rgb), float3(color2.rgb), t);
    float ca = cover * mix(float(color1.a), float(color2.a), t);
    half4 halo = half4(half3(rgb) * half(ca), half(ca));
    half4 body = src * half(clamp(fill, 0.0, 1.0));
    return body + halo * (1.0 - body.a);
}
